  {view==='products'&&<><div className="collection-toolbar"><label className="search-box"><Search size={16}/><input placeholder="Tìm tuyến, điểm đến…" aria-label="Tìm chương trình" value={query} onChange={e=>{setContactSelection({scope:'',ids:[]});setQuery(e.target.value);}}/></label><span>{data.products.filter(matches).length} chương trình</span></div><div className="product-grid">{data.products.filter(matches).map((p,i)=><article className="product-card" key={rid(p)}><div className={`product-visual landscape-${i%3}`}><span className="destination-tag"><MapPinned size={13}/>{s(p,'destination')}</span><div className="visual-sun"/><div className="visual-mountain left"/><div className="visual-mountain right"/><span className="duration-tag">{s(p,'duration')}</span></div><div className="product-content"><div className="product-overline"><span>{s(p,'tier')}</span><span>Phiên bản {s(p,'version')}</span></div><h2>{s(p,'name')}</h2><div className="product-price">{money(p.price,s(p,'currency'))}<small> / {s(p,'unit')}</small></div><p className="product-conditions">{s(p,'conditions')}</p><div className="product-footer"><span><CalendarDays size={13}/>Đến {date(p.validUntil)}</span><button className="icon-button" title="Tài liệu chương trình" onClick={()=>setDetail({kind:"product",row:p})}><FileText size={16}/></button><RowActions resource="products" row={p} onAction={setCrudSelection}/></div></div></article>)}</div>{!data.products.filter(matches).length&&<section className="panel"><Empty icon={MapPinned} title="Thêm hành trình đầu tiên" description="Lưu chương trình và bảng giá để chuẩn bị nội dung dành cho đối tác."/></section>}</>}
