  {campaignDetail&&!modal&&<Dialog wide title={s(campaignDetail.campaign,'name')} description={`${campaignDetail.eligible} người nhận đạt bộ lọc · ${campaignDetail.blocked} không đạt / đã xử lý`} onClose={()=>setCampaignDetail(null)}><div className="detail-body"><button className="text-button ai-detail-link" onClick={()=>askAssistant('campaign',campaignDetail.campaign)}>✦ Hỏi trợ lý về chiến dịch này</button><div className="detail-meta"><Badge value={s(campaignDetail.campaign,'status')}/>{campaignDetail.product?<><span>{s(campaignDetail.product,'name')}</span><span>Bảng giá v{s(campaignDetail.product,'version')}</span></>:<span>Không gắn chương trình / bảng giá</span>}</div><label className="checkbox-label"><input type="checkbox" checked={!!campaignDetail.campaign.allowTemplateResend} disabled={!['draft','approved','paused'].includes(s(campaignDetail.campaign,'status'))||campaignDetail.delivery.some(r=>Number(r.attempts)>0||r.claimedAt)} onChange={async event=>{const enabled=event.target.checked;try{await api('campaigns/'+rid(campaignDetail.campaign),{action:'template-resend',allowTemplateResend:enabled},'PATCH');await openCampaign(rid(campaignDetail.campaign));flash('Đã đổi chế độ gửi lại. Kiểm tra danh sách rồi duyệt lại.');}catch(error){flash((error as Error).message);}}}/>Cho phép gửi lại mẫu đã gửi trong chiến dịch này</label><div className="campaign-detail-grid"><section><h3>Bản xem trước theo người nhận</h3><label>Người nhận<select aria-label="Người nhận xem trước" value={Math.min(previewIndex,Math.max(0,campaignDetail.recipients.length-1))} onChange={event=>setPreviewIndex(Number(event.target.value))}>{campaignDetail.recipients.map((recipient,index)=><option key={recipient.id} value={index}>{recipient.email}</option>)}</select></label>{(campaignDetail.recipients[previewIndex]||campaignDetail.recipients[0])?.preview?<div className="email-preview"><div><strong>Đến:</strong> {(campaignDetail.recipients[previewIndex]||campaignDetail.recipients[0]).email}</div><div><strong>Tiêu đề:</strong> {(campaignDetail.recipients[previewIndex]||campaignDetail.recipients[0]).preview?.subject}</div><pre>{(campaignDetail.recipients[previewIndex]||campaignDetail.recipients[0]).preview?.body}</pre><small>Thư gửi giữ nguyên nội dung đã cá nhân hóa. Nếu cần chữ ký, hãy thêm vào mẫu thư.</small></div>:<p className="muted">Nội dung chưa đủ biến để xem trước.</p>}</section><CampaignRecipients key={rid(campaignDetail.campaign)} recipients={campaignDetail.recipients} onRefresh={()=>openCampaign(rid(campaignDetail.campaign))} policy={s(campaignDetail.campaign,'recipientPolicy')||'eligible_only'} editable={['draft','approved','paused'].includes(s(campaignDetail.campaign,'status'))&&!campaignDetail.delivery.some(r=>Number(r.attempts)>0||r.claimedAt)} onPolicyChange={async recipientPolicy=>{await api('campaigns/'+rid(campaignDetail.campaign),{action:'recipient-policy',recipientPolicy},'PATCH');await openCampaign(rid(campaignDetail.campaign));flash('Đã lưu điều kiện. Kiểm tra danh sách rồi duyệt lại.');}}/></div>{campaignDetail.delivery.some(d=>d.step===1||d.error)&&<section className="delivery-log"><h3>Lịch sử xử lý</h3>{campaignDetail.delivery.map(d=><div key={rid(d)}><span>{s(d,'email')} · Bước {Number(d.step)+1}</span><Badge value={s(d,'status')}/>{d.status==='unknown'&&data.user.role==='admin'&&<button className="text-button" onClick={()=>setModal({title:"Đối soát lượt gửi",description:"Kiểm tra log nhà cung cấp theo Message-ID: "+s(d,'messageId'),fields:[{name:"result",label:"Kết quả từ nhà cung cấp",required:true,options:[{value:"accepted",label:"Nhà cung cấp đã nhận"},{value:"not_sent",label:"Xác nhận chưa gửi · đóng lượt này"}]},{name:"evidence",label:"Bằng chứng đối soát (ít nhất 20 ký tự)",type:"textarea",required:true}],onSubmit:async body=>{await api('reconcile/'+rid(d),body);await openCampaign(rid(campaignDetail.campaign));}})}>Đối soát</button>}{d.error&&<small>{s(d,'error')}</small>}</div>)}</section>}</div><footer className="dialog-footer"><button className="button secondary" onClick={()=>setCampaignDetail(null)}>Đóng</button>{data.user.role==='admin'&&<button className="button secondary" onClick={()=>setModal({title:"Gửi thử nội bộ",description:"Địa chỉ thử cần có trong TEST_RECIPIENTS và SMTP đã cấu hình.",fields:[{name:"email",label:"Email nội bộ được phép",type:"email",required:true},{name:"contactId",label:"Cá nhân hóa theo liên hệ",required:true,options:campaignDetail.recipients.map(r=>({value:r.id,label:r.email}))}],onSubmit:async body=>{await api('campaign-test/'+rid(campaignDetail.campaign),body);flash("Đã gửi bản thử nội bộ.");}})}>Gửi thử</button>}{['draft','approved','paused'].includes(s(campaignDetail.campaign,'status'))&&<button className="button secondary" disabled={approving||!campaignDetail.eligible} onClick={async()=>{const detail=campaignDetail;const approve=async()=>{setApproving(true);try{await api('campaigns/'+rid(detail.campaign),{action:'approve',previewToken:detail.previewToken,acceptExclusions:detail.blocked>0},'PATCH');await openCampaign(rid(detail.campaign));flash(`Đã duyệt ${detail.eligible} người nhận; bỏ qua ${detail.blocked}.`);}catch(e){await openCampaign(rid(detail.campaign));throw e;}finally{setApproving(false);}};if(detail.blocked){setModal({title:'Xác nhận danh sách gửi',description:`Gửi cho ${detail.eligible} người nhận đạt; bỏ qua ${detail.blocked} người nhận không đạt. Lý do được lưu trong lịch sử chiến dịch.`,fields:[{name:'confirmation',label:'Xác nhận phạm vi gửi',required:true,options:[{value:'confirmed',label:`Chỉ gửi ${detail.eligible} người nhận đạt điều kiện`}]}],submitLabel:'Duyệt danh sách đạt',onSubmit:approve});}else{try{await approve();}catch(e){flash((e as Error).message);}}}}><ShieldCheck size={15}/>{approving?'Đang duyệt…':`Duyệt ${campaignDetail.eligible} người nhận`}</button>}{['approved','paused'].includes(s(campaignDetail.campaign,'status'))&&<button className="button primary" onClick={()=>setModal({title:'Lên lịch chiến dịch',fields:[{name:'scheduledAt',label:'Thời điểm bắt đầu',type:'datetime-local',required:true}],submitLabel:'Lưu lịch gửi',onSubmit:async body=>{await api('campaigns/'+rid(campaignDetail.campaign),{...body,action:'schedule'},'PATCH');await openCampaign(rid(campaignDetail.campaign));flash('Đã lên lịch. Lượt gửi vẫn kiểm tra kết nối và điều kiện hiện tại.');}})}><CalendarDays size={15}/>Lên lịch</button>}{['scheduled','running'].includes(s(campaignDetail.campaign,'status'))&&<button className="button secondary" onClick={async()=>{await act('campaigns/'+rid(campaignDetail.campaign),{action:'pause'},'PATCH');await openCampaign(rid(campaignDetail.campaign));}}><Pause size={15}/>Tạm dừng</button>}{!['completed','cancelled'].includes(s(campaignDetail.campaign,'status'))&&<button className="button danger" onClick={async()=>{await act('campaigns/'+rid(campaignDetail.campaign),{action:'cancel'},'PATCH');await openCampaign(rid(campaignDetail.campaign));}}>Hủy chiến dịch</button>}</footer></Dialog>}
  {detail&&!modal&&<Dialog wide title={['account','product'].includes(detail.kind)?s(detail.row,'name'):detail.kind==='message'?s(detail.row,'subject'):s(detail.row,'title')} description={detail.kind==='account'?'Hồ sơ đối tác và các bước tiếp theo':detail.kind==='message'?s(detail.row,'accountName'):s(detail.row,'accountName')} onClose={()=>setDetail(null)}><div className="detail-body"><button className="text-button ai-detail-link" onClick={()=>askAssistant(detail.kind as typeof entityTypes[number],detail.row)}>✦ Nhờ trợ lý hỗ trợ hồ sơ này</button>{detail.kind==='account'&&<><div className="detail-meta"><Badge value={s(detail.row,'stage')}/><span>{s(detail.row,'region')}</span><span>{s(detail.row,'segment')}</span><span>{s(detail.row,'tier')}</span></div><p className="pre-wrap">{s(detail.row,'notes')||'Chưa có ghi chú.'}</p><h3>Người liên hệ</h3>{data.contacts.filter(c=>c.accountId===detail.row.id).map(c=><div className="detail-contact" key={rid(c)}><section><strong>{s(c,'name')||'Chưa có tên'}</strong><small>{s(c,'email')}</small></section><RowActions resource="contacts" row={c} onAction={setCrudSelection}/><Badge value={s(c,'consentStatus')}/><button className="text-button" onClick={async()=>{try{const result=await api('validate-email/'+rid(c)) as {message:string};flash(result.message);}catch(error){flash((error as Error).message);}}}>Kiểm tra MX</button><button className="text-button" disabled={c.consentStatus==='suppressed'} onClick={()=>reviewContact(c)}>Đánh giá <ArrowUpRight size={14}/></button></div>)}<div className="detail-actions"><button className="button secondary" onClick={()=>createContact(rid(detail.row))}><Plus size={14}/>Thêm liên hệ</button><button className="button secondary" onClick={()=>createTask(rid(detail.row))}><CheckCircle2 size={14}/>Thêm công việc</button><button className="button primary" onClick={()=>createRfq(rid(detail.row))}><ClipboardList size={14}/>Tạo RFQ</button></div><h3>Yêu cầu báo giá</h3>{data.rfqs.filter(r=>r.accountId===detail.row.id).map(r=><div className="detail-contact" key={rid(r)}><strong>{s(r,'title')}</strong><Badge value={s(r,'status')}/></div>)}<h3>Lịch sử quyền nhận tin</h3><p className="muted">Các lần đánh giá được lưu trong nhật ký kiểm toán. Người đã từ chối luôn được loại khỏi lượt gửi mới.</p></>}
  {detail.kind==='product'&&<><p className="pre-wrap">{s(detail.row,'conditions')}</p><PrivateFiles parentType="product" parentId={rid(detail.row)}/></>}{detail.kind==='rfq'&&<><div className="detail-meta"><Badge value={s(detail.row,'status')}/><span>{s(detail.row,'destination')}</span><span>{s(detail.row,'pax')} khách</span><span>Ngày đi: {date(detail.row.departureDate)}</span></div><p className="pre-wrap">{s(detail.row,'notes')||'Chưa có yêu cầu bổ sung.'}</p><div className="quote-stats"><div><small>Ngân sách dự kiến</small><strong>{money(detail.row.budget)}</strong></div><div><small>Hạn trả báo giá</small><strong>{date(detail.row.deadline)}</strong></div><div><small>Lợi nhuận gộp</small><strong>{money(detail.row.grossMargin)}</strong></div></div><PrivateFiles parentType="rfq" parentId={rid(detail.row)}/><h3>Các phiên bản báo giá</h3>{data.quotes.filter(q=>q.rfqId===detail.row.id).map(q=><article className="quote-version" key={rid(q)}><RowActions resource="quotes" row={q} onAction={setCrudSelection}/><div><strong>Phiên bản {s(q,'version')} · {money(q.amount,s(q,'currency'))}</strong><span>Hiệu lực đến {date(q.validUntil)}</span></div><p>{s(q,'conditions')}</p></article>)}<div className="detail-actions"><button className="button secondary" onClick={()=>setCrudSelection({resource:'rfqs',row:detail.row,mode:'edit'})}>Cập nhật RFQ</button><button className="button primary" onClick={()=>createQuote(detail.row)}><Plus size={15}/>Thêm báo giá</button></div></>}
  {detail.kind==='message'&&<><div className="detail-meta"><Badge value={s(detail.row,'classification')}/><span>{s(detail.row,'email')}</span><span>{date(detail.row.receivedAt,true)}</span></div><pre className="message-body">{s(detail.row,'body')}</pre><div className="detail-actions"><a className="button secondary" href={`mailto:${s(detail.row,'email')}?subject=${encodeURIComponent('Re: '+s(detail.row,'subject'))}`}><Mail size={15}/>Trả lời bằng hộp thư</a><button className="button primary" onClick={()=>createRfq(s(detail.row,'accountId'))}>Tạo RFQ <ArrowRight size={15}/></button></div><h3>Phân loại phản hồi</h3><div className="classification-buttons">{['positive','rfq','not_now','wrong_person','unsubscribe'].map(value=><button className="button secondary small-button" key={value} onClick={async()=>{await act('messages/'+rid(detail.row),{classification:value},'PATCH');setDetail(null);}}>{statusNames[value]}</button>)}</div></>}
  </div><footer className="dialog-footer"><button className="button secondary" onClick={()=>setDetail(null)}>Đóng</button>{detail.kind==='account'&&<button className="button primary" onClick={()=>setCrudSelection({resource:'accounts',row:detail.row,mode:'edit'})}><Pencil size={15}/>Cập nhật hồ sơ</button>}</footer></Dialog>}
